fn solve(input: Vec<char>) -> Vec<char> {
    // Input length is strictly positive per statement.
    let mut s = input;

    // 1) Remove a single trailing '\n' if present.
    if matches!(s.last(), Some('\n')) {
        s.pop();
    }

    // 2) Repeatedly trim leading/trailing whitespace from the set: ' ', '\t', '\n', '\r'.
    // Doing this with indices is equivalent to repeatedly removing one-by-one until clean.
    fn is_ws(c: char) -> bool {
        matches!(c, ' ' | '\t' | '\n' | '\r')
    }

    let mut start = 0usize;
    let mut end = s.len(); // exclusive

    while start < end && is_ws(s[start]) {
        start += 1;
    }
    while start < end && is_ws(s[end - 1]) {
        end -= 1;
    }

    let trimmed = &s[start..end];

    // 3) Check password validity:
    // - length >= 5
    // - has at least one lowercase ASCII, uppercase ASCII, digit ASCII
    let mut has_lower = false;
    let mut has_upper = false;
    let mut has_digit = false;

    for &c in trimmed {
        if ('a'..='z').contains(&c) {
            has_lower = true;
        } else if ('A'..='Z').contains(&c) {
            has_upper = true;
        } else if ('0'..='9').contains(&c) {
            has_digit = true;
        }
    }

    let ok = trimmed.len() >= 5 && has_lower && has_upper && has_digit;

    if ok {
        "Correct\n".chars().collect()
    } else {
        "Too weak\n".chars().collect()
    }
}